import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"科学新闻核实","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/science-news/index.md","filePath":"topics/science-news/index.md"}'),e={name:"topics/science-news/index.md"};function i(a,t,g,u,l,d){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="科学新闻核实" tabindex="-1">科学新闻核实 <a class="header-anchor" href="#科学新闻核实" aria-label="Permalink to &quot;科学新闻核实&quot;">​</a></h1><p>用户转来的科学新闻 / 自媒体科普摘要的<strong>信源核实记录</strong>。</p><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zhishiku-reading/topics/science-news/news-verification-2026-10-23.html">news-verification-2026-10-23.md</a></td><td>2026-10-23 那条五段式「科学日报」18 条<strong>逐条核实</strong>：一页速查表（真实出处 + DOI）、三类失真归类、AI 段 4 条 36kr 标题党打假、<strong>两处自我更正记录</strong></td></tr><tr><td><a href="/zhishiku-reading/topics/physics/cosmic-inflation-origin.html">../physics/cosmic-inflation-origin.md</a></td><td>2026-10-24 转来的《揭秘宇宙起源新理论》：<strong>四类失真之&quot;关系错位&quot;的首例</strong>（&quot;暴胀取代大爆炸&quot;实为前置扩展）+ 暴胀能否被实验证实的完整回答</td></tr><tr><td><a href="/zhishiku-reading/topics/space-energy/lunar-industrial-satellite.html">../space-energy/lunar-industrial-satellite.md</a></td><td>2026-10-24 王钦文 × 马兆远访谈收尾的&quot;月球工业伴星&quot;构想核实：<strong>时间错位首例</strong>——实为 <strong>1979-04-30 NASA 报告</strong>（General Dynamics/Convair，NAS9-15560，30 座 × 10 GW）；2026 现状 = Caltech MAPLE（EIRP 3.2 W / 地面 &lt;0.1 µW）、中国逐日工程/OMEGA、2026-05-18 新华社百米级千瓦级</td></tr><tr><td><a href="/zhishiku-reading/topics/career-observation/ma-zhaoyuan-interview-ai-involution.html">../career-observation/ma-zhaoyuan-interview-ai-involution.md</a></td><td>2026-10-24 同批访谈的<strong>人物归属核实</strong>：马兆远身份由南方科技大学官网核实（牛津物理博士、2009 中科院研究员、为天宫四号设计载荷）；<strong>&quot;访谈型材料的失真高发区不在观点，而在&quot;时间坐标&quot;与&quot;归属坐标&quot;</strong></td></tr><tr><td><a href="/zhishiku-reading/topics/ai-system-architecture/openai-ai-native-organization.html">../ai-system-architecture/openai-ai-native-organization.md</a></td><td>2026-10-24《OpenAI 内部 AI 实践：可读→可操作→可迭代》：<strong>第五类失真首例</strong>——框架与官方 2026 发布轨迹逐段对齐（<strong>可信</strong>），但<strong>细节零出处 + 反面省略</strong>（员工数反向翻倍 / 内部 Agent 越权访问澳洲 Medicare / 失准监控 / HPIM 95% 未开放）</td></tr><tr><td><a href="/zhishiku-reading/topics/ai-system-architecture/sky-001-engineering-world-model.html">../ai-system-architecture/sky-001-engineering-world-model.md</a></td><td>2026-10-24《SKY-001 全球首个工程世界模型》：<strong>程度夸大 + 口径错位 + 选择性省略</strong>的复合案例。官方原话是 &quot;<strong>while matching its performance</strong>（79.7% vs 79.1%）&quot;，被转述成&quot;<strong>精度还更高</strong>&quot;；&quot;成本降低 150 倍&quot;直译自官方病句 &quot;costs 150 times less&quot;（正确＝<strong>降到 1/150</strong>）；官方口径自身三处打架（50× / 51× / &quot;100 times&quot;）。★ 缺的六件事：<strong>仅 waitlist</strong> / <strong>官方自承草图与三维几何可能对不上</strong> / <strong>&quot;首个&quot;系自我宣称</strong> / <strong>HN 5 分 0 评论</strong> / <strong>基准自建自评</strong> / <strong>Astra 非各维度最强基线</strong></td></tr><tr><td><a href="/zhishiku-reading/topics/career-observation/lin-xiaolong-wow-story-verification.html">../career-observation/lin-xiaolong-wow-story-verification.md</a></td><td>2026-10-24《美发店创始人玩〈魔兽世界〉翻身》：<strong>第五类失真第二例，也是&quot;社交平台故事&quot;型首次</strong>——<strong>三面检索全部落空</strong>（Bing 原样返回&quot;没有与此相关的结果&quot;、Google News 零命中、搜狗 11,210 条全是<strong>同名网络小说</strong>《林小龙 叶小五》）。★ 判定成本极低：<strong>一次三面检索即可定性</strong>。★ 但同时确认了被故事勾出的两个硬事实：德鲁伊＝治疗职业之一；&quot;一次成功恢复心气&quot;＝Bandura 自我效能感中<strong>最强</strong>的来源</td></tr></tbody></table><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Google News RSS 定位原始报道 → 抓原文正文 → <strong>CrossRef API 核 DOI</strong> → PubMed E-utilities 核论文。 逐条给四段：① 真实来源（期刊/机构 + 日期 + 标题原文）② 具体研究内容（谁做、方法、关键数字、DOI）③ 中文转述 vs 真实的差异/夸大 ④ 核实级别。</p><h2 id="五类失真-可复用的检查清单" tabindex="-1">五类失真（可复用的检查清单） <a class="header-anchor" href="#五类失真-可复用的检查清单" aria-label="Permalink to &quot;五类失真（可复用的检查清单）&quot;">​</a></h2><ol><li><strong>时间错位</strong> —— 旧报道（数月前）被当作&quot;今日新闻&quot;重发。ScienceDaily 会把 6 月的新闻稿在 10 月<strong>再推送</strong>一次，中文&quot;日报&quot;照抄。</li><li><strong>程度夸大</strong> —— 理论预测 / 模型输出 / 设计蓝图 → &quot;已实现 / 突破 / 首个&quot;。凡&quot;降低 100 倍&quot;&quot;效率提升 40 倍&quot;都要问：是<strong>实测</strong>还是<strong>算出来的</strong>？</li><li><strong>主体 / 口径 / 方向错位</strong> —— 仪器张冠李戴（相机锐度说成日冕仪）、基因名错（GFAP 写成 FOXD1）、把 GDP <strong>总量</strong>说成<strong>增量</strong>、<strong>把 &quot;reversal（向下逆转）&quot; 读成 &quot;反弹（向上）&quot;</strong>。</li><li><strong>关系错位（2026-10-24 新增）</strong> —— 把&quot;<strong>补充 / 前置扩展</strong>&quot;说成&quot;<strong>范式取代</strong>&quot;。案例：暴胀理论被包装成&quot;正在取代热大爆炸&quot;，实际它是大爆炸模型的极早期扩展（暴胀之后宇宙&quot;continued to expand&quot;，接续而非替代）。<strong>比夸数字更隐蔽，因为它听起来更&quot;革命&quot;</strong>——而且<strong>文中后半段往往自己讲对了</strong>，只有标题和开头在博眼球。</li><li><strong>无具名信源的内幕叙述（2026-10-24 新增）</strong> —— &quot;<strong>某公司内部就是这么干的</strong>&quot;这类<strong>组织行为叙述</strong>，全篇不点名任何人／文章／演讲。案例：《OpenAI 内部 AI 实践》的<strong>三层框架与官方发布轨迹逐段对齐（可信）</strong>，但&quot;一个周末上百个 Agent 涌入&quot;&quot;语音 30 分钟出报告&quot;<strong>零出处</strong>，且<strong>系统性地剪掉了反面事实</strong>（同期员工数在翻倍、内部 Agent 已越权访问政府服务器、官方自己在做失准监控、内部模型 95% 不对外开放）。 <strong>判据</strong>：<strong>只能采信其框架，不能采信其数字</strong>；并且必须<strong>主动去查它没说的那部分</strong>——反面事实往往是核实工作中信息量最大的地方。 <strong>第二例（2026-10-24，社交平台故事型）</strong>：<strong>美发店创始人玩《魔兽世界》翻身</strong>。与前例相反，这一条<strong>连框架都无法落地</strong>——<strong>三面检索全部落空</strong>（Bing 明确&quot;没有与此相关的结果&quot;、Google News 零命中、搜狗命中全是<strong>同名网络小说</strong>）。 <strong>新增判据</strong>：<strong>&quot;传闻型故事&quot;的定性成本极低</strong>——<strong>Bing（原样零结果）+ 搜狗（看命中是不是同名小说/同名剧）+ B站（风控看 412）</strong> 三面走一遍，10 分钟内可定&quot;不可核实&quot;。定性后<strong>不要停在&quot;查不到&quot;</strong>，而要把故事<strong>勾出来的可核实问题</strong>答完（本例：德鲁伊是不是治疗职业、&quot;一次成功恢复心气&quot;有没有理论支撑）——<strong>这才是能沉淀的部分</strong>。</li></ol><h2 id="铁律" tabindex="-1">铁律 <a class="header-anchor" href="#铁律" aria-label="Permalink to &quot;铁律&quot;">​</a></h2><ul><li><strong>凡&quot;突破 / 首个 / 破解 / 再创新低&quot;字样，先查发布日期 + 原文措辞</strong>，再信中文。</li><li><strong>ScienceDaily 标题本身就是第一层失真源</strong>（never-ending / reversed / this one age / stunning reversal）—— 中文直译会再放大一层。</li><li>核实到&quot;未经同行评议 / 不可复现 / 器件未造 / 仅立项&quot;这类限定，<strong>必须写进结论</strong>，它们往往正是&quot;争议&quot;的真实内容。</li><li><strong>不编造</strong>：&quot;我查不到&quot;是合法状态；子代理的自报结论也须亲验后再落盘。</li></ul><hr><blockquote><p>关键词：科学新闻核实、信源核实、36kr 标题党、时间错位、程度夸大、主体错位、方向读反、关系错位、前置扩展、范式取代、无具名信源、内幕叙述、组织行为叙述、传闻型故事、社交平台故事、归属核实、访谈型材料、OpenAI AI 原生、可读可操作可迭代、DOI 核实、CrossRef、ScienceDaily 标题党、黎曼猜想、TheoPhysEval、GPT-6 Astra、SKY-001、Skyfall、工程世界模型、Enterprise World Model、CAD、BIM、Sam Pasupalak、Maluuba、Zanvastro、GFAP、Alexander 病、GIMLI、钍-229 核时钟、BVR-19、SHOQ、DT-109、暴胀、真空暴涨、宇宙起源、BICEP2、原初引力波、可证伪性、月球工业伴星、空间太阳能电站、逐日工程、马兆远、魔兽世界、World of Warcraft、德鲁伊、治疗职业、林小龙、美发店、自我效能感、self-efficacy、mastery experience、习得性无助、learned helplessness、社会缓冲、可控感</p></blockquote>',12)])])}const h=o(e,[["render",i]]);export{c as __pageData,h as default};
